CREATE SEQUENCE branch_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE truck_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE grain_type_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE weighing_scale_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE transport_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE inventory_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE weighing_SEQ START WITH 1 INCREMENT BY 50;
CREATE SEQUENCE scale_state_SEQ START WITH 1 INCREMENT BY 50;
CREATE TABLE branch (id BIGINT PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE truck (id BIGSERIAL PRIMARY KEY, plate VARCHAR(255) NOT NULL UNIQUE, tare_kg NUMERIC(14,3) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE grain_type (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, purchase_price_per_ton NUMERIC(14,4) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE weighing_scale (id BIGSERIAL PRIMARY KEY, external_id VARCHAR(255) NOT NULL UNIQUE, branch_id BIGINT NOT NULL REFERENCES branch(id), credential_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE transport (id BIGSERIAL PRIMARY KEY, truck_id BIGINT NOT NULL REFERENCES truck(id), branch_id BIGINT NOT NULL REFERENCES branch(id), grain_id BIGINT NOT NULL REFERENCES grain_type(id), status VARCHAR(32) NOT NULL, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ);
CREATE INDEX idx_transport_truck_status ON transport(truck_id,status);
CREATE TABLE inventory (id BIGSERIAL PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branch(id), grain_id BIGINT NOT NULL REFERENCES grain_type(id), available_kg NUMERIC(14,3) NOT NULL, UNIQUE(branch_id,grain_id));
CREATE TABLE weighing (id BIGSERIAL PRIMARY KEY, idempotency_key VARCHAR(255) NOT NULL UNIQUE, plate VARCHAR(255) NOT NULL, gross_kg NUMERIC(14,3) NOT NULL, tare_kg NUMERIC(14,3) NOT NULL, net_kg NUMERIC(14,3) NOT NULL, purchase_price_per_ton NUMERIC(14,4) NOT NULL, cargo_cost NUMERIC(14,2) NOT NULL, margin NUMERIC(5,4) NOT NULL, estimated_sale_price NUMERIC(14,2) NOT NULL, scale_id BIGINT NOT NULL REFERENCES weighing_scale(id), grain_id BIGINT NOT NULL REFERENCES grain_type(id), transport_id BIGINT NOT NULL REFERENCES transport(id), weighed_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_weighing_time ON weighing(weighed_at);
CREATE TABLE scale_state (id BIGSERIAL PRIMARY KEY, scale_plate_key VARCHAR(255) NOT NULL UNIQUE, plate VARCHAR(255) NOT NULL, stable_samples BIGINT NOT NULL, mean_kg NUMERIC(14,3) NOT NULL, min_kg NUMERIC(14,3) NOT NULL, max_kg NUMERIC(14,3) NOT NULL, last_seen TIMESTAMPTZ);
